automatically_repaired_code:
content = note_content['content']
lines = content.split('\n')
songs = []

for line in lines:
    line = line.strip()
    if not line or line.startswith('#'):
        continue
    if line.startswith('- '):
        parts = line[2:].split(' BY ')
        if len(parts) < 2:
            continue
        song_title = parts[0]
        artists = parts[1].split(', ')
        release_info = line.split(' RELEASED_AT ')
        release_month = None
        if len(release_info) > 1:
            release_month = release_info[1].strip()
        songs.append({
            'title': song_title,
            'artists': artists,
            'release_month': release_month
        })

print(songs)

